*** Begin Patch
*** Add File: /app/deck_work/slides/helpers.js
+const path = require('path');
+
+const W = 10;
+const H = 5.625;
+const FONT = 'Arial';
+
+function addBg(slide, theme, variant = 'light') {
+  slide.background = { color: variant === 'dark' ? theme.primary : theme.bg };
+  if (variant === 'dark') {
+    slide.addShape('rect', { x: 0, y: 0, w: W, h: H, fill: { color: theme.primary }, line: { color: theme.primary } });
+    slide.addShape('rect', { x: 7.2, y: 0, w: 2.8, h: H, fill: { color: theme.secondary, transparency: 18 }, line: { color: theme.secondary, transparency: 100 } });
+  } else {
+    slide.addShape('rect', { x: 0, y: 0, w: W, h: H, fill: { color: theme.bg }, line: { color: theme.bg } });
+    slide.addShape('rect', { x: 0, y: 0, w: 0.16, h: H, fill: { color: theme.accent }, line: { color: theme.accent } });
+  }
+}
+
+function addTitle(slide, title, theme, opts = {}) {
+  const dark = opts.dark || false;
+  slide.addText(title, {
+    x: opts.x || 0.48, y: opts.y || 0.32, w: opts.w || 8.8, h: opts.h || 0.64,
+    fontFace: FONT, fontSize: opts.size || 25, bold: true,
+    color: dark ? theme.bg : theme.primary, margin: 0.02, breakLine: false, fit: 'shrink'
+  });
+}
+
+function addKicker(slide, text, theme, opts = {}) {
+  slide.addText(text.toUpperCase(), {
+    x: opts.x || 0.5, y: opts.y || 0.18, w: opts.w || 3.5, h: 0.18,
+    fontFace: FONT, fontSize: 6.5, bold: true, charSpace: 1.2,
+    color: opts.dark ? theme.light : theme.muted, margin: 0
+  });
+}
+
+function addFooter(slide, n, theme, dark = false) {
+  slide.addText(String(n).padStart(2, '0'), {
+    x: 9.33, y: 5.13, w: 0.38, h: 0.2, fontFace: FONT, fontSize: 7,
+    bold: true, align: 'center', color: dark ? theme.light : theme.muted, margin: 0
+  });
+  slide.addText('LLM API integrity audit', {
+    x: 0.5, y: 5.16, w: 2.2, h: 0.16, fontFace: FONT, fontSize: 6.5,
+    color: dark ? theme.light : theme.muted, margin: 0
+  });
+}
+
+function addBadge(slide, text, x, y, w, theme, opts = {}) {
+  slide.addShape('roundRect', {
+    x, y, w, h: opts.h || 0.34, rectRadius: 0.06,
+    fill: { color: opts.fill || theme.goldLight },
+    line: { color: opts.line || theme.gold, transparency: opts.lineTrans ?? 15 }
+  });
+  slide.addText(text, {
+    x: x + 0.07, y: y + 0.08, w: w - 0.14, h: 0.12,
+    fontFace: FONT, fontSize: opts.size || 7.5, bold: true, align: 'center',
+    color: opts.color || theme.primary, margin: 0, fit: 'shrink'
+  });
+}
+
+function addCard(slide, x, y, w, h, theme, opts = {}) {
+  slide.addShape('roundRect', {
+    x, y, w, h, rectRadius: 0.08,
+    fill: { color: opts.fill || 'FFFFFF', transparency: opts.transparency || 0 },
+    line: { color: opts.line || theme.border, transparency: opts.lineTrans ?? 0 },
+    shadow: opts.shadow === false ? undefined : { type: 'outer', color: '000000', opacity: 0.08, blur: 1.5, angle: 45, distance: 1 }
+  });
+}
+
+function addBullets(slide, bullets, x, y, w, h, theme, opts = {}) {
+  const runs = [];
+  bullets.forEach((b, i) => {
+    runs.push({ text: `${i ? '\n' : ''}• ${b}`, options: { breakLine: false } });
+  });
+  slide.addText(runs, {
+    x, y, w, h, fontFace: FONT, fontSize: opts.size || 10.5, color: opts.color || theme.text,
+    breakLine: false, fit: 'shrink', valign: 'top', margin: 0.03,
+    paraSpaceAfterPt: opts.paraSpaceAfterPt || 8, breakLine: false
+  });
+}
+
+function addMiniLabel(slide, text, x, y, w, theme, opts = {}) {
+  slide.addText(text, {
+    x, y, w, h: opts.h || 0.18, fontFace: FONT, fontSize: opts.size || 7.5,
+    bold: opts.bold !== false, color: opts.color || theme.muted, margin: 0, fit: 'shrink'
+  });
+}
+
+function img(name) {
+  return path.join('/app/benchmark/assets', name);
+}
+
+module.exports = { W, H, FONT, addBg, addTitle, addKicker, addFooter, addBadge, addCard, addBullets, addMiniLabel, img };
*** End Patch
PATCH

